//A Simple 2D Lighting Trick; Author: Joshy20XX, Date: January 21, 2025

vec3 getBackgroundColor(vec2 uv) {
    uv += 0.5; // remap uv from <-0.5,0.5> to <0,1>
    vec3 gradientStartColor = vec3(1., 0., 1.);
    vec3 gradientEndColor = vec3(0., 1., 1.);
    return mix(gradientStartColor, gradientEndColor, uv.y); // gradient goes from bottom to top
}



float sdfCircle(vec2 uv, float r, vec2 offset) {
  float x = uv.x - offset.x;
  float y = uv.y - offset.y;

  return length(vec2(x, y)) - r;
}

float sdfSquare(vec2 uv, float size, vec2 offset) {
  float x = uv.x - offset.x;
  float y = uv.y - offset.y;

  return max(abs(x), abs(y)) - size;
}

vec3 drawScene(vec2 uv) {;
  vec3 col = getBackgroundColor(uv);
  float circle = sdfCircle(uv, 0.1, vec2(-0.2, 0));
  float square = sdfSquare(uv, 0.07, vec2(0.2, 0));

  col = mix(vec3(0, 0, 1), col, step(0., circle));
  col = mix(vec3(1, 0, 0), col, step(0., square));

  return col;
}

vec3 drawDarkScene(vec2 uv) {;
  vec3 col = getBackgroundColor(uv);
  float circle = sdfCircle(uv, 0.1, vec2(-0.2, 0));
  float square = sdfSquare(uv, 0.07, vec2(0.2, 0));

  col = mix(vec3(0, 0, 0), col, step(0., circle));
  col = mix(vec3(0,0,0), col, step(0., square));

  return col;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
  //Have two versions of the UV, light and dark
  vec2 uv = fragCoord/iResolution.xy; // <0, 1>
  uv -= 0.5; // <-0.5,0.5>
  uv.x *= iResolution.x/iResolution.y; // fix aspect ratio

  vec2 uv_shadowed = fragCoord/iResolution.xy; // <0, 1>
  uv_shadowed -= 0.5; // <-0.5,0.5>
  uv_shadowed.x *= iResolution.x/iResolution.y; // fix aspect ratio

  vec3 col = drawScene(uv);
  vec3 col_shad = drawDarkScene(uv_shadowed);

  //Define your shape of choice
  float circle = smoothstep(.5, .3, sdfCircle(uv, -.25, vec2(sin(iTime/1.) * .3, 0)));

  //Blend the two UVs with the circle's size and the appropriate sharpness
  if (circle < .45) col += col_shad;
  col *= smoothstep(.5, 1., circle);

  //Add the shadowed color with the main color to get the results
  col += col_shad;

  // Output to screen
  fragColor = vec4(col,1.0);
}
